"""Generate the single Reeltrip product documentation from the shared screen catalog."""
from pathlib import Path
import html,json,subprocess
ROOT=Path(__file__).resolve().parent
OUT=ROOT/'docs'
E=lambda value:html.escape(str(value),quote=True)
catalog=json.loads(subprocess.check_output(['node','-e',"global.window={};require('./assets/catalog.js');process.stdout.write(JSON.stringify(window.REEL_SCREENS))"],cwd=ROOT,text=True))
for i,s in enumerate(catalog,1):s['id']=f'B-{i:02d}'
def page(title,body):
 return f'<!doctype html><html lang="ko"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{E(title)} · 릴트립</title><link rel="stylesheet" href="../assets/docs.css"></head><body><main class="hub"><nav><a href="../index.html">프로젝트</a> · <a href="product.html">전체 기획</a> · <a href="developer-handoff.html">개발 인계</a> · <a href="../app/index.html">앱</a></nav><h1>{E(title)}</h1>{body}</main></body></html>'
def section(title,body):return '<section class="docsection"><h2>'+E(title)+'</h2>'+body+'</section>'
plan='''<p>영상과 직접 입력으로 장소를 모으고, 내 여행을 만든 뒤 현지 메이트의 제안을 비교하는 매칭 서비스다.</p><h3>탭별 역할</h3><ul><li>발견: 영상 링크로 장소 찾기.</li><li>내 장소: 장소 보관함. 영상·수동 추가, 선택 날짜 여행에 담기. 일정에서 빼도 보관함에는 유지.</li><li>내 여행: 보관한 장소로 날짜·순서·체류시간을 구성한다.</li><li>메이트: 여행 메이트 찾기 / 도착한 제안. 특정 메이트 지정 대신 여행 공개 후 복수 제안을 비교한다.</li><li>마이: 프로필 편집, 진행 중인 여행과 활동 바로가기. 설정 아이콘 안에 언어·모드 전환, 도움말·약관·데이터 관리.</li></ul><h3>확정 흐름</h3><p>여행 공개 → 메이트들의 일정·가격 제안 → 여행자 선택·예약 요청 → 메이트 확정 대기 → 메이트가 10% 매칭 수수료 결제 → 예약 확정 → 현장에서 여행비 전액 현금 직접 지급.</p><p>240,000원 여행이면 메이트는 플랫폼에 24,000원을 선결제하고, 여행자는 메이트에게 240,000원을 현금으로 직접 지급한다. 플랫폼은 여행비를 수납·송금하지 않는다.</p><h3>현재 구현 범위</h3><p>고객·메이트 동일 앱, 운영자는 별도 웹. 한국어·영어 로컬 시제품. 1개 여행·1개 공개 요청, 선택한 하루를 공개한다. 복수 제안과 가이드별 재발행은 지원한다. 실제 영상 분석·인증·DB·PG·푸시·다중 사용자 동기화는 미구현이다.</p>'''
policies='''<ul><li>공개 HTTPS Shorts/Reels 링크와 장소 확인을 지원한다. 실제 추출은 미연동이다.</li><li>현재 요청 폼은 최소 48시간 전·성수·최대 4시간/6곳·위치 확인 장소를 검사한다. 추가 지역·수동 장소의 권역 판별은 후속 개발이다.</li><li>같은 요청에 복수 제안을 보존한다. 동일 메이트의 재발행만 교체하며 고객이 선택한 버전·금액을 예약에 고정한다.</li><li>여행자 선택만으로 확정하지 않는다. 선택된 메이트의 매칭 수수료 10% 결제 검증 후에만 확정한다.</li><li>현금 수령 상태는 예약 확정·여행 완료와 별개다. 자동 수령 처리하지 않는다.</li><li>확정 전 철회와 확정 후 취소 검토를 분리한다. 플랫폼은 여행비 자동 환불을 제공하지 않는다.</li><li>수수료 결제 유예시간·노쇼·취소 시 반환·VAT 및 분쟁 정책은 미확정이다. 이전 자동 환불률을 적용하지 않는다.</li><li>닉네임 중복 금지: NFKC·공백 제거·소문자 기준. 자신의 기존 이름 유지 허용. 변경 후 재확인과 저장 직전 재검사. 실제 서버 UNIQUE 제약은 별도 구현한다.</li></ul>'''
ia=''.join(section({'customer':'고객 앱','guide':'메이트 앱','admin':'운영 웹'}[role],'<ul>'+''.join(f'<li>{s["id"]} <a href="../{"admin" if role=="admin" else "app"}/index.html#{s["route"]}">{E(s["name"])}</a> · {E(s["route"])}</li>' for s in catalog if s['role']==role)+'</ul>') for role in ['customer','guide','admin'])
spec='';screens=''
for s in catalog:
 spec+=f'<article class="specitem" id="spec-{s["id"]}"><h3>{s["id"]} {E(s["name"])}</h3><p><a href="../{"admin" if s["role"]=="admin" else "app"}/index.html#{s["route"]}">화면 열기</a></p><dl>'+''.join('<dt>'+label+'</dt><dd>'+E(s[field])+'</dd>' for field,label in [('input','입력'),('rule','규칙'),('action','행동·전이'),('states','상태'),('accept','인수 기준')])+'</dl></article>'
 screens+=f'<article id="wire-{s["id"]}"><h3>{s["id"]} {E(s["name"])}</h3><ol>'+''.join('<li>'+E(z)+'</li>' for z in s['zones'])+'</ol></article>'
technical='''<p>원본: assets/app.js, catalog.js, access.js, revenue.js. 영어는 i18n/build_english.py로 생성한다. 기존 B-* ID와 localStorage 키는 내부 호환성을 위해 유지한다.</p><ul><li>library: 장소 보관함. board/days: 날짜별 일정.</li><li>request: 공개 여행 스냅샷. proposals: 메이트별 견적 배열. quote: 현재 상세 선택 제안.</li><li>booking: 선택 제안 스냅샷, feeRate=0.1, feeAmount, feeStatus, paymentMethod=cash, cashStatus.</li><li>프로필·읽음 상태·닉네임 디렉터리는 현재 로컬 저장이다. 서버 인증·소유권·개인정보 보호는 별도 구현이다.</li></ul><h3>서버 연결 계약</h3><p>여행자 예약 요청은 awaiting_mate_fee. PG 서버 응답·서명 웹훅의 금액/통화/주문/선택 메이트 ID를 대조한 후 confirmed. 클라이언트 성공 값만으로 확정 금지. 서버 가격 스냅샷·트랜잭션·결제 멱등성·취소와 결제 경합 보상 처리를 구현한다. 닉네임 canonical UNIQUE와 소유권 검사는 서버에서 원자적으로 수행한다.</p><p><a href="developer-handoff.html">상세 계약·미확정 사항</a></p>'''
qa='''<p>코드 검사는 브라우저·기기 시각 검증이나 실제 서버 통합 검증을 대체하지 않는다.</p><ul><li>node tests/startup_checks.cjs: 전체 entry script 초기화·기존 저장 데이터 로드.</li><li>node tests/navigation_checks.cjs: 한영 경로·닉네임·복수 제안·현금 매칭 상태 전이.</li><li>node tests/access_checks.cjs: 역할별 시연 접근.</li><li>node tests/google_map_checks.js: 지도 폴백·좌표.</li><li>python3 tests/static_checks.py: 문서·경로·화면 추적성.</li><li>상위 폴더에서 node reeltrip-planning/tests/tower_seed_checks.cjs: 기존 데이터 업그레이드.</li></ul><p>출시 전 실제 인증·서버·PG 실패/중복/철회 경합·푸시·기기별 화면·접근성·운영 정책을 별도 검증한다.</p>'''
legal='''<p>현금 직접 거래와 10% 매칭 수수료는 제품 결정이다. 이 설명만으로 법적 의무나 면제 여부가 확정된 것은 아니다.</p><p>실제 운영 주체·계약 상대방·자격·등록·보험·현금 거래 책임·수수료 세금·취소/노쇼 정책은 출시 전에 검토하고 확정한다. 이전 직접 여행 운영 모델의 법적 결론을 그대로 전용하지 않는다.</p>'''
blocks=[('plan','서비스 기획',plan),('ia','정보 구조',ia),('screens','화면 구성',screens),('specification','기능 명세',spec),('policies','운영 정책',policies),('technical','개발 설계',technical),('qa','검증 기준',qa),('legal','미확정 운영 사항',legal)]
(OUT/'product.html').write_text(page('릴트립 기획·명세',''.join(section(title,body) for slug,title,body in blocks)))
for slug,title,body in blocks:(OUT/f'{slug}.html').write_text(page(title,body))
(OUT/'screen-spec.json').write_text(json.dumps(catalog,ensure_ascii=False,indent=2)+'\n')
print(f'Generated single-service documents: {len(catalog)} screens.')
